// Oncology engine verified against R: survival 3.5.8 (coxph, cox.zph), cmprsk (cuminc, Gray's test),
// survRM2 (rmst2), clinfun (ph2simon) and stats::binom.test.
// Reference values: tests/fixtures/oncology-reference.json, regenerated by tests/fixtures/oncology-reference.R.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as O from '../web/lib/oncology.mjs';

const R = JSON.parse(readFileSync(new URL('./fixtures/oncology-reference.json', import.meta.url)));
const close = (a, b, tol, label = '') => { [].concat(a).forEach((v, i) => assert.ok(Math.abs(v - [].concat(b)[i]) <= tol, `${label}[${i}] ${v} vs R ${[].concat(b)[i]}`)); };
const L = R.lung, X = L.age.map((a, i) => [a, L.sex[i], L.ecog[i]]);

for (const ties of ['efron', 'breslow']) {
  test(`Cox PH (${ties}) matches R survival::coxph on the NCCTG lung data`, () => {
    const f = O.coxph(L.time, L.status, X, ['age', 'sex', 'ph.ecog'], { ties }), r = R[`cox_${ties}`];
    assert.equal(f.n, L.time.length);
    close(f.coef.map(c => c.coef), r.coef, 1e-9, 'coef');
    close(f.coef.map(c => c.se), r.se, 1e-9, 'se');
    close(f.loglik, r.loglik, 1e-8, 'loglik');
    close(f.tests.lr.chi2, r.lr, 1e-8, 'LR');
    close(f.tests.score.chi2, r.score, 1e-8, 'score');
    close(f.tests.wald.chi2, r.wald, 0.006, 'Wald (R prints 2 d.p.)');
    close(f.concordance, r.concordance, 1e-12, 'concordance');
    close(f.coef.map(c => c.hr), r.coef.map(Math.exp), 1e-9, 'HR');
  });
  test(`PH test (${ties}) matches R survival::cox.zph(transform = "km")`, () => {
    const f = O.coxph(L.time, L.status, X, ['age', 'sex', 'ph.ecog'], { ties }), z = O.coxZph(f), r = R[`cox_${ties}`];
    close([...z.table.map(t => t.chi2), z.global.chi2], r.zph_chisq, 1e-9, 'chisq');
    close([...z.table.map(t => t.p), z.global.p], r.zph_p, 1e-9, 'p');
  });
}

test('stratified Cox matches R coxph(... + strata(sex))', () => {
  const f = O.coxph(L.time, L.status, L.age.map((a, i) => [a, L.ecog[i]]), ['age', 'ph.ecog'], { strata: L.sex });
  close(f.coef.map(c => c.coef), R.cox_strata.coef, 1e-9, 'coef');
  close(f.coef.map(c => c.se), R.cox_strata.se, 1e-9, 'se');
});

test('Cox rejects degenerate input', () => {
  assert.throws(() => O.coxph([1, 2], [1, 0], [[1], [2]]), /more than/);
  assert.throws(() => O.coxph([1, 2, 3, 4], [0, 0, 0, 1], [[1], [2], [3], [4]]), /two events/);
});

test('RMST and two-arm comparison match R survRM2::rmst2', () => {
  const r = O.rmst2(L.time, L.status, L.sex.map(s => s - 1), 365);
  close([r.arms[0].rmst, r.arms[0].se], R.rmst.arm0, 1e-9, 'arm0');
  close([r.arms[1].rmst, r.arms[1].se], R.rmst.arm1, 1e-9, 'arm1');
  close([r.difference.est, r.difference.lower, r.difference.upper, r.difference.p], R.rmst.diff, 1e-9, 'difference');
  close([r.ratio.est, r.ratio.lower, r.ratio.upper, r.ratio.p], R.rmst.ratio, 1e-9, 'ratio');
  assert.throws(() => O.rmst(L.time, L.status, 1e6), /exceeds/);
});

test('cumulative incidence and variance match R cmprsk::cuminc', () => {
  const C = R.cr, idx = C.group.map((g, i) => (g === 'A' ? i : -1)).filter(i => i >= 0);
  const a = O.cumulativeIncidence(idx.map(i => C.time[i]), idx.map(i => C.status[i]), 1);
  close(R.cr_cif_A1.times.map(t => a.at(t).est), R.cr_cif_A1.est, 1e-12, 'group A est');
  close(R.cr_cif_A1.times.map(t => a.at(t).var), R.cr_cif_A1.var, 1e-14, 'group A var');
  const c1 = O.cumulativeIncidence(C.time, C.status, 1), c2 = O.cumulativeIncidence(C.time, C.status, 2), T = R.cr_cif_all.times;
  close(T.map(t => c1.at(t).est), R.cr_cif_all.est1, 1e-12, 'cause 1');
  close(T.map(t => c1.at(t).var), R.cr_cif_all.var1, 1e-14, 'cause 1 var');
  close(T.map(t => c2.at(t).est), R.cr_cif_all.est2, 1e-12, 'cause 2');
  close(T.map(t => c2.at(t).var), R.cr_cif_all.var2, 1e-14, 'cause 2 var');
});

test("Gray's test matches R cmprsk::cuminc tests", () => {
  const C = R.cr;
  [1, 2].forEach((cause, i) => {
    const g = O.grayTest(C.time, C.status, C.group, { cause });
    close(g.chi2, R.cr_gray.stat[i], 1e-9, `cause ${cause} stat`);
    close(g.p, R.cr_gray.p[i], 1e-9, `cause ${cause} p`);
    assert.equal(g.df, R.cr_gray.df[i]);
  });
});

test('Simon two-stage designs match R clinfun::ph2simon', () => {
  for (const s of R.simon) {
    const d = O.simonTwoStage(s.p0, s.p1, s.alpha, s.beta);
    assert.deepEqual([d.optimal.r1, d.optimal.n1, d.optimal.r, d.optimal.n], s.optimal.slice(0, 4), `optimal ${s.p0}/${s.p1}`);
    assert.deepEqual([d.minimax.r1, d.minimax.n1, d.minimax.r, d.minimax.n], s.minimax.slice(0, 4), `minimax ${s.p0}/${s.p1}`);
    close([d.optimal.en0, d.optimal.pet0], s.optimal.slice(4, 6), 1e-8, 'optimal EN0/PET0');
    close([d.minimax.en0, d.minimax.pet0], s.minimax.slice(4, 6), 1e-8, 'minimax EN0/PET0');
  }
});

test('Clopper–Pearson intervals match R binom.test', () => {
  for (const [x, n, lo, hi] of R.binom) { const c = O.binomialCI(x, n); close([c.lower, c.upper], [lo, hi], 1e-10, `${x}/${n}`); }
});

test('BOIN boundaries match Liu & Yuan (2015) for a 30% target', () => {
  const b = O.boinBoundaries(0.3);
  close([b.lambdaE, b.lambdaD], [0.2365, 0.3585], 5e-5, 'lambda');
  assert.deepEqual(b.table(6), { escalateIfAtMost: 1, deescalateIfAtLeast: 3 });
});

test('RECIST 1.1 categories', () => {
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 100, currentSum: 65 }).overall, 'PR');
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 60, currentSum: 73 }).overall, 'PD');   // +21.7% and +13 mm from nadir
  assert.equal(O.recist({ baselineSum: 30, nadirSum: 20, currentSum: 24 }).overall, 'SD');     // +20% from nadir but only +4 mm (not PD); -20% from baseline (not PR)
  assert.equal(O.recist({ baselineSum: 40, nadirSum: 25, currentSum: 30 }).overall, 'PD');     // +20% and +5 mm from nadir
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 90, currentSum: 95 }).overall, 'SD');
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 0, currentSum: 0, allTargetsResolved: true }).overall, 'CR');
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 0, currentSum: 0, allTargetsResolved: true, nonTargetCR: false }).overall, 'PR');
  assert.equal(O.recist({ baselineSum: 100, nadirSum: 90, currentSum: 80, newLesions: true }).overall, 'PD');
});
